"""Every method, in `hello_ok.capabilities` order."""


class EventEntry(TypedDict):
    """A log entry: replayed after `session.subscribe`, then live."""

    v: int
    reply_to: None
    event: Literal["entry"]
    payload: Entry


class EventStream(TypedDict):
    """A live model stream chunk."""

    v: int
    reply_to: None
    event: Literal["stream"]
    payload: StreamPayload


class EventIdle(TypedDict):
    """The session went idle after a turn."""

    v: int
    reply_to: None
    event: Literal["idle"]
    payload: Idle


class EventApproval(TypedDict):
    """A tool call waits for a human; answer it with `approval.answer`."""

    v: int
    reply_to: None
    event: Literal["approval"]
    payload: ApprovalCard


class EventJobFinished(TypedDict):
    """A job finished while no turn ran; `job.list` shows it until the next turn delivers it."""

    v: int
    reply_to: None
    event: Literal["job_finished"]
    payload: JobFinished


class EventError(TypedDict):
    """A failure outside any request (a lagging client, a log write that did not land)."""

    v: int
    reply_to: None
    event: Literal["error"]
    payload: ErrorPayload


Event = Union[
    "EventEntry",
    "EventStream",
    "EventIdle",
    "EventApproval",
    "EventJobFinished",
    "EventError",
]
"""A server-initiated frame: what `Client.events()` yields."""
